// 114-01: the component catalogue in the app — katalog.json (generated by the harness), the catalogue module (lazy load, type lookup,
// build-up in the format of aufbauten_layer, type GUID from the harness), the catalogue materials as group "Katalog" (ids kat:<key>) and
// the wall field `katalog_typ` resolved by aufbauVon BEFORE `composite`; walls without the field stay exactly as before.
// Byte equality of katalog.json with a fresh export is the harness test (harness/tests/test_bauteilkatalog_app_export.py).
import { describe, it, before } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import {
  KATALOG_PRAEFIX, KATALOG_GRUPPE, ladeKatalog, setzeKatalog, katalogGeladen, katalogTypen, katalogTyp, katalogAufbau, katalogTypGuid,
  katalogBaustoff, katalogMaterial, katalogMaterialien,
} from "@core/lib/bauteil/katalog/index.js";
import { MATERIAL_KATALOG, materialById, alleMaterialien } from "@core/lib/bauteil/materialien.js";
import { WALL_COMPOSITES, WAND_KLASSEN, aufbauVon, kernLage, prioritaetVorschlag } from "@core/lib/bauteil/aufbauten.js";
import { wandDicke_m } from "@core/lib/bauteil/referenz.js";
import { steckbrief } from "@core/lib/bauteil/steckbrief.js";
import { EN } from "@core/lib/i18nTeile/bauteilkatalog-114.js";
import { findeTreffer } from "../../tools/sperrliste.mjs";

const DATEI = new URL("../../packages/nova-core/src/lib/bauteil/katalog/katalog.json", import.meta.url);
const TEXT = readFileSync(DATEI, "utf8");
const ROH = JSON.parse(TEXT);
const IFC_GUID = /^[0-9A-Za-z_$]{22}$/;
const KS_WDVS = "ks-wdvs-42-cm@1";
/** Final type GUID of "KS + WDVS 42 cm" in the harness IFC files (pinned by harness/tests/test_bauteilkatalog.py, own namespace). */
const KS_WDVS_GUID = "1XEVHbDKvIjAOSAuxNaIEz";

before(async () => { assert.equal(await ladeKatalog(), true); });

describe("114-01 katalog.json (erzeugt vom Harness)", () => {
  it("Kopf: Quelle elmonkey-core, Hinweis zum Neu-Erzeugen, SHA-256 des Inhalts", () => {
    assert.match(ROH.quelle, /^elmonkey-core \d+\.\d+\.\d+$/);
    assert.match(ROH.hinweis, /python -m harness\.bauteilkatalog app-export/);
    // The hash is taken over Python's canonical JSON (floats such as 0.0 keep their ".0", which JSON.parse loses), so its VALUE is checked
    // by the harness test together with the byte equality; here only its form.
    assert.match(ROH.inhalt_sha256, /^[0-9a-f]{64}$/);
  });
  it("Format: LF, Einrückung 1, Zeilenende am Schluss; Grundbestand 42 Typen, 113 Baustoffe, sortiert", () => {
    assert.ok(!TEXT.includes("\r"), "CRLF in katalog.json");
    assert.ok(TEXT.endsWith("}\n"));
    assert.ok(TEXT.startsWith('{\n "baustoffe": [\n  {\n'), "Einrückung 1, Schlüssel sortiert");
    assert.equal(ROH.typen.length, 42);
    assert.equal(ROH.baustoffe.length, 113);
    const schl = ROH.typen.map((/** @type {any} */ t) => `${t.schluessel}@${t.version}`);
    assert.deepEqual(schl, [...schl].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)));
    const bs = ROH.baustoffe.map((/** @type {any} */ b) => b.schluessel);
    assert.deepEqual(bs, [...bs].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)));
  });
  it("jeder Typ trägt die Felder des Plans; jede Schicht verweist auf einen Baustoff des Exports", () => {
    const felder = ["din276", "dicke_m", "klasse", "kurzname", "langname", "predefined_type", "pset_common", "rohling", "schichten", "schluessel", "typ_guid", "version"];
    for (const t of ROH.typen) {
      for (const f of felder) assert.ok(f in t, `${t.schluessel}: ${f} fehlt`);
      for (const s of t.schichten) {
        assert.ok(katalogBaustoff(s.baustoff), `${t.schluessel}: Baustoff ${s.baustoff} fehlt`);
        assert.ok(s.dicke_m >= 0 && s.dicke_m < 2, `${t.schluessel}: Dicke ${s.dicke_m} m`);
      }
      if (t.klasse === "IfcDoor" || t.klasse === "IfcWindow") assert.ok(t.oeffnung && t.oeffnung.breite_m > 0 || t.rohling, `${t.schluessel}: Öffnung`);
    }
  });
  it("neutral: keine Treffer der gehashten Sperrliste (dieselbe Liste wie projektneutral.test.js)", () => {
    const { eintraege } = JSON.parse(readFileSync(new URL("./sperrliste.sha256.json", import.meta.url), "utf8"));
    assert.ok(eintraege.length >= 42, "Sperrliste nicht gelesen");
    assert.deepEqual(findeTreffer(TEXT, eintraege).map((/** @type {any} */ t) => `Eintrag #${t.nr}`), []);
  });
});

describe("114-01 Katalog-Modul", () => {
  it("lädt einmal (dieselbe Zusage), danach geladen", () => {
    assert.equal(ladeKatalog(), ladeKatalog());
    assert.equal(katalogGeladen(), true);
  });
  it("katalogTyp: Schlüssel = höchste Version, schluessel@version exakt, Unbekanntes → null", () => {
    const t = katalogTyp(KS_WDVS);
    assert.equal(t?.schluessel, "ks-wdvs-42-cm");
    assert.equal(katalogTyp("ks-wdvs-42-cm"), t);
    assert.equal(katalogTyp(" ks-wdvs-42-cm@1 "), t);
    for (const r of ["ks-wdvs-42-cm@2", "ks-wdvs-42-cm@0", "ks-wdvs-42-cm@x", "ks-wdvs-42-cm@1@1", "gibt-es-nicht", "", null, undefined]) {
      assert.equal(katalogTyp(/** @type {any} */ (r)), null, String(r));
    }
  });
  it("katalogTypen filtert nach Klasse; Rohlinge nur auf Wunsch", () => {
    const waende = katalogTypen({ klasse: "IfcWall" });
    assert.ok(waende.length > 20 && waende.every((t) => t.klasse === "IfcWall" && !t.rohling));
    assert.ok(!katalogTypen().some((t) => t.rohling));
    assert.equal(katalogTypen({ rohlinge: true }).length, 42);
    assert.ok(katalogTypen({ klasse: "IfcWall", rohlinge: true }).some((t) => t.schluessel === "rohling-wand"));
  });
  it("Typ-GUID kommt aus dem Export: 22 Zeichen IFC-Alphabet, eindeutig, gleich der Harness-GUID", () => {
    const guids = katalogTypen({ rohlinge: true }).map((t) => katalogTypGuid(t));
    for (const g of guids) assert.match(String(g), IFC_GUID);
    assert.equal(new Set(guids).size, guids.length);
    assert.equal(katalogTypGuid(KS_WDVS), KS_WDVS_GUID);
    assert.equal(katalogTypGuid(katalogTyp(KS_WDVS)), KS_WDVS_GUID);
    assert.equal(katalogTypGuid("gibt-es-nicht"), null);
  });
  it("kein uuid5-Nachbau in JS: das Modul erzeugt keine GUIDs (D-MH-03)", () => {
    const quelle = readFileSync(new URL("../../packages/nova-core/src/lib/bauteil/katalog/index.js", import.meta.url), "utf8");
    // code only: the comments say WHERE the GUID is made (uuid5 in the harness) and may name it
    const code = quelle.replace(/\/\*[\s\S]*?\*\//g, "").replace(/\/\/.*$/gm, "");
    assert.doesNotMatch(code, /uuid|sha-?1|createHash|stabileGuid|crypto|^import\s/im);
  });
  it("katalogAufbau: Format von aufbauten_layer — Dicke mm, Material kat:<baustoff>, Funktion aus der Rolle, Priorität aus dem Baustoff", () => {
    const a = katalogAufbau(katalogTyp(KS_WDVS));
    assert.ok(a);
    assert.equal(a.id, "kat:ks-wdvs-42-cm@1");
    assert.equal(a.name, "KS + WDVS 42 cm");
    assert.deepEqual(a.skins.map((s) => s.thickness), [10, 160, 240, 10]);
    assert.deepEqual(a.skins.map((s) => s.material), ["kat:kunstharzputz-370", "kat:xps-730", "kat:kalksandstein-635", "kat:gipsputz-360"]);
    assert.deepEqual(a.skins.map((s) => s.funktion), ["bekleidung", "sonstig", "kern", "bekleidung"]);
    assert.deepEqual(a.skins.map((s) => s.prioritaet), a.skins.map((s) => katalogBaustoff(s.material.slice(4))?.verschneidungsprioritaet));
    // stud wall: layers without a role carry no stated function (the app proposes one), 12.5 mm boards stay exact
    const gk = katalogAufbau(katalogTyp("gk-2-lagen-12-5-cm"));
    assert.deepEqual(gk?.skins.map((s) => s.thickness), [12.5, 12.5, 75, 12.5, 12.5]);
    assert.equal(gk?.skins[1].funktion, undefined);
    assert.equal(katalogAufbau(katalogTyp("tuer-innen-1-flg-uz-holz-88-5x213-5")), null, "Tür hat keinen Schichtaufbau");
    assert.equal(katalogAufbau(null), null);
    // a foil stated with 0 m is left out (a skin needs a positive thickness); the total stays the type's thickness
    const hr = katalogTyp("holzrahmen-abgehangt-35-5-cm");
    const hra = katalogAufbau(hr);
    assert.equal(hra?.skins.length, (hr?.schichten.length ?? 0) - 1);
    assert.ok(Math.abs((hra?.skins.reduce((a, s) => a + s.thickness, 0) ?? 0) / 1000 - Number(hr?.dicke_m)) < 1e-9);
  });
  it("vor dem Laden antwortet jede Abfrage leer; danach wieder voll", async () => {
    setzeKatalog(null);
    try {
      assert.equal(katalogGeladen(), false);
      assert.equal(katalogTyp(KS_WDVS), null);
      assert.deepEqual(katalogTypen(), []);
      assert.equal(materialById("kat:kalksandstein-635"), null);
      // a wall naming a catalogue type keeps its old build-up meanwhile and says which reference is open
      const w = aufbauVon({ katalog_typ: KS_WDVS, composite: "cavity" });
      assert.equal(w.name, "Klinker + Dämmung + KS (39 cm)");
      assert.equal(w.katalogOffen, KS_WDVS);
    } finally {
      assert.equal(await ladeKatalog(), true);
    }
    assert.ok(katalogTyp(KS_WDVS));
  });
});

describe("114-01 Baustoffe als Gruppe „Katalog“ (D-MH-02)", () => {
  it("die 22 App-Materialien bleiben unverändert; 113 Katalog-Baustoffe kommen dazu, ohne ID-Kollision", () => {
    assert.equal(MATERIAL_KATALOG.length, 22);
    assert.ok(MATERIAL_KATALOG.every((m) => !m.id.startsWith(KATALOG_PRAEFIX) && m.gruppe === undefined));
    assert.equal(materialById("ks"), MATERIAL_KATALOG.find((m) => m.id === "ks"));
    const alle = alleMaterialien();
    assert.equal(alle.length, 22 + 113);
    assert.equal(new Set(alle.map((m) => m.id)).size, alle.length);
    assert.equal(katalogMaterialien().length, 113);
    assert.ok(katalogMaterialien().every((m) => m.gruppe === KATALOG_GRUPPE && m.id === KATALOG_PRAEFIX + m.schluessel));
  });
  it("materialById löst kat:<schluessel> auf: Name, Farbe, λ, Dichte aus dem Katalog; Kategorie und Schraffur abgebildet", () => {
    const m = materialById("kat:kalksandstein-635");
    const b = katalogBaustoff("kalksandstein-635");
    assert.ok(m && b);
    assert.equal(m.name, b.name);
    assert.equal(m.color, b.farbe);
    assert.equal(m.lambda, b.kennwerte.lambda_W_mK);
    assert.equal(m.dichte, b.kennwerte.dichte_kg_m3);
    assert.equal(m.kategorie, "Massiv");
    assert.equal(m.mu, null, "μ ist im Katalog unbekannt");
    assert.equal(katalogMaterial("kat:gibt-es-nicht"), null);
    assert.equal(materialById("kat:gibt-es-nicht"), null);
    assert.equal(materialById("kat:xps-730")?.kategorie, "Dämmung");
  });
  it("λ = 0 (Platzhalter-Baustoffe der Quelle) ist keine Wärmeleitfähigkeit → null", () => {
    const null_lambda = ROH.baustoffe.filter((/** @type {any} */ b) => !(b.kennwerte.lambda_W_mK > 0));
    assert.ok(null_lambda.length > 0);
    for (const b of null_lambda) assert.equal(materialById(KATALOG_PRAEFIX + b.schluessel)?.lambda, null, b.schluessel);
  });
  it("Prioritätsvorschlag eines Katalog-Baustoffs = seine Katalog-Priorität; App-Materialien unverändert", () => {
    assert.equal(prioritaetVorschlag("kat:kalksandstein-635"), katalogBaustoff("kalksandstein-635")?.verschneidungsprioritaet);
    assert.equal(prioritaetVorschlag("beton"), 850);
    assert.equal(prioritaetVorschlag("ks"), 650);
  });
  it("Gruppenname hat einen englischen Text", () => {
    assert.equal(EN[KATALOG_GRUPPE], "Catalogue");
  });
});

describe("114-01 Wandfeld katalog_typ", () => {
  it("eine Wand mit katalog_typ ks-wdvs-42-cm@1 bekommt den Schichtaufbau des Katalogtyps (0,42 m, 4 Schichten, kat:-Materialien) — vor composite", () => {
    const a = aufbauVon({ katalog_typ: KS_WDVS, composite: "single24", thickness: 0.3 });
    assert.equal(a.quelle, "composite");
    assert.equal(a.name, "KS + WDVS 42 cm");
    assert.equal(a.dicke_m, 0.42);
    assert.equal(a.schichten.length, 4);
    assert.ok(a.schichten.every((s) => String(s.material).startsWith(KATALOG_PRAEFIX)));
    assert.deepEqual(a.schichten.map((s) => s.funktion), ["bekleidung", "sonstig", "kern", "bekleidung"]);
    assert.equal(a.funktionAbgeleitet, false, "alle vier Schichten haben eine Rolle");
    assert.equal(a.prioritaetAbgeleitet, false, "Priorität steht im Katalog");
    assert.deepEqual(a.katalog, { schluessel: "ks-wdvs-42-cm", version: 1, typ_guid: KS_WDVS_GUID, klasse: "IfcWall" });
    assert.equal(a.katalogOffen, undefined);
    assert.deepEqual(kernLage(a.schichten), { aussen_m: 0.17, kern_m: 0.24, abgeleitet: false });
  });
  it("Element-Override je Schicht gilt auch für Katalogtypen", () => {
    const a = aufbauVon({ katalog_typ: KS_WDVS, schicht_funktion: { 1: "kern" }, schicht_prioritaet: { 0: 5 } });
    assert.equal(a.schichten[1].funktion, "kern");
    assert.equal(a.schichten[0].prioritaet, 5);
  });
  it("ein unbekannter Katalogtyp fällt auf composite/klasse/Dicke zurück und wird als offen gemeldet", () => {
    const ohne = aufbauVon({ composite: "cavity" });
    const mit = aufbauVon({ katalog_typ: "gibt-es-nicht@1", composite: "cavity" });
    assert.deepEqual({ ...mit, katalogOffen: undefined }, { ...ohne, katalogOffen: undefined });
    assert.equal(mit.katalogOffen, "gibt-es-nicht@1");
    // a door type has no layers: it cannot be a wall build-up
    assert.equal(aufbauVon({ katalog_typ: "tuer-innen-1-flg-uz-holz-88-5x213-5", thickness: 0.2 }).quelle, "dicke");
  });
  it("Wände ohne katalog_typ verhalten sich unverändert (keine neuen Schlüssel im Ergebnis)", () => {
    const faelle = [...WALL_COMPOSITES.map((c) => ({ composite: c.id })), ...Object.keys(WAND_KLASSEN).map((k) => ({ klasse: k })), { thickness: 0.2 }, {}];
    for (const el of faelle) {
      const a = aufbauVon(el);
      assert.ok(!("katalog" in a) && !("katalogOffen" in a), JSON.stringify(el));
      assert.ok(a.schichten.every((s) => !String(s.material).startsWith(KATALOG_PRAEFIX)));
    }
    assert.equal(aufbauVon({ composite: "single24" }).dicke_m, 0.24);
  });
  it("Wanddicke im Plan folgt dem Katalogtyp; ohne Feld wie bisher", () => {
    assert.equal(wandDicke_m({ katalog_typ: KS_WDVS, composite: "single24", thickness: 0.3 }), 0.42);
    assert.equal(wandDicke_m({ katalog_typ: "gibt-es-nicht", thickness: 0.3 }), 0.3);
    assert.equal(wandDicke_m({ thickness: 0.3 }), 0.3);
    assert.equal(wandDicke_m({ composite: "single24" }), 0.24);
  });
  it("der Steckbrief zeigt den Katalogaufbau mit Kern", () => {
    const s = steckbrief({ a: { x: 0, z: 0 }, b: { x: 5, z: 0 }, katalog_typ: KS_WDVS, height: 2.75 }, "wand-aussen");
    assert.equal(s.aufbau?.name, "KS + WDVS 42 cm");
    assert.equal(s.aufbau?.dicke_m, 0.42);
    assert.deepEqual(s.aufbau?.kern, { aussen_m: 0.17, kern_m: 0.24, abgeleitet: false });
  });
});

describe("114-01 Review-Fixes", () => {
  before(async () => { await ladeKatalog(); });

  it("Plan-Dicke = Summe der Schichtliste, auch bei 12,5-mm-Lagen (eine Quelle)", () => {
    for (const t of katalogTypen({ klasse: "IfcWall" })) {
      const w = { katalog_typ: `${t.schluessel}@${t.version}` };
      const a = aufbauVon(w);
      if (!a.katalog) continue;
      assert.equal(wandDicke_m(w), a.dicke_m, t.schluessel);
    }
  });

  it("Verweis auf einen Tür-/Fenstertyp: katalogOhneSchichten statt katalogOffen", () => {
    const fenster = katalogTypen({ klasse: "IfcWindow" })[0];
    assert.ok(fenster, "Fenstertyp im Katalog");
    const a = aufbauVon({ katalog_typ: fenster.schluessel, thickness: 0.3 });
    assert.equal(a.katalogOffen, undefined);
    assert.deepEqual(a.katalogOhneSchichten, { schluessel: fenster.schluessel, klasse: "IfcWindow" });
    assert.equal(aufbauVon({ katalog_typ: "gibt-es-nicht" }).katalogOffen, "gibt-es-nicht");
  });
});
